334	  const issue = requireFound(
335	    await issueRepo.findIssueById(input.orgId, input.issueId),
336	    "Issue",
337	    input.issueId,
338	  );
339	  assertCan(actor, "comment:create", issueResource(issue));
340	  assertNotArchived("Issue", issue.id, issue);
341	
342	  const verdict = await consumeRateLimit(input.orgId, COMMENT_CREATE_BUCKET);
343	  if (!verdict.allowed) {
344	    throw new Error(
345	      `Comment rate limit reached; try again after ${verdict.resetAt}`,
346	    );
