453	/**
454	 * Union of the ids the client already resolved (optimistic UI) and the ones
455	 * parsed out of the body server-side. The server list wins on disagreement.
456	 */
457	async function resolveMentionedUsers(
458	  orgId: OrgId,
459	  body: string,
460	  clientProvided: readonly UserId[],
461	): Promise<readonly UserId[]> {
462	  const members = await memberRepo.listMembers({
463	    orgId,
464	    limit: MENTION_LOOKUP_LIMIT,
465	    cursor: null,
466	  });
467	
468	  const resolved = resolveMentions(body, members.items);
469	  const known = new Set(members.items.map((member) => member.userId));
470	
471	  return [
472	    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
473	  ];
