475	/**
476	 * Extracts `@handle` mentions from comment bodies and resolves them to member
477	 * ids.
478	 *
479	 * A handle is the local part of a member's email address, lowercased — that
480	 * is what the comment composer autocompletes and what `CommentService` feeds
481	 * to the notification fan-out, so extraction and resolution must agree
482	 * exactly. Mentions inside code spans and fenced blocks are ignored.
483	 */
484	import type { UserId } from "@/types/common";
485	import type { MemberWithUser } from "@/types/member";
486	
487	/** `@` must start the line or follow whitespace/punctuation, never an email. */
488	const MENTION_PATTERN = /(^|[\s(<[])@([a-z0-9][a-z0-9._-]{0,38}[a-z0-9])/gi;
489	
490	function withoutCode(body: string): string {
491	  return body.replace(/```[\s\S]*?```/g, " ").replace(/`[^`]*`/g, " ");
492	}
493	
494	/** The handle Taskflow addresses a member by, derived from their email. */
495	export function handleOf(member: MemberWithUser): string {
496	  return (member.user.email.split("@")[0] ?? "").toLowerCase();
497	}
498	
499	/** Every distinct handle mentioned, in first-appearance order. */
500	export function extractMentions(body: string): readonly string[] {
501	  const seen = new Set<string>();
502	  const handles: string[] = [];
503	
504	  for (const match of withoutCode(body).matchAll(MENTION_PATTERN)) {
505	    const handle = (match[2] ?? "").toLowerCase();
506	    if (handle === "" || seen.has(handle)) continue;
507	    seen.add(handle);
508	    handles.push(handle);
509	  }
510	
511	  return handles;
512	}
513	
514	/**
515	 * Maps the mentions in `body` onto the ids of members who actually exist in
516	 * the organization. Unknown handles are silently dropped — a typo must never
517	 * fail the comment write.
518	 */
519	export function resolveMentions(
520	  body: string,
521	  members: readonly MemberWithUser[],
522	): readonly UserId[] {
523	  const byHandle = new Map<string, UserId>();
524	  for (const member of members) {
525	    byHandle.set(handleOf(member), member.userId);
526	  }
527	
528	  const resolved: UserId[] = [];
529	  const seen = new Set<UserId>();
530	  for (const handle of extractMentions(body)) {
531	    const userId = byHandle.get(handle);
532	    if (userId === undefined || seen.has(userId)) continue;
533	    seen.add(userId);
534	    resolved.push(userId);
535	  }
536	
537	  return resolved;
538	}
