540	/** Wraps every mention in a span so the comment renderer can style it. */
541	export function highlightMentions(body: string): string {
542	  return body.replace(
543	    MENTION_PATTERN,
544	    (_match, prefix: string, handle: string) =>
545	      `${prefix}<span class="mention">@${handle}</span>`,
546	  );
547	}
