687	/**
688	 * Turns the session cookie into an `Actor`. Everything server-side that needs authorization starts here.
689	 *
690	 * Must call (do not reimplement): assertOrgScope
691	 */
692	import { hashToken, randomToken } from "@/lib/hash";
693	import { assertOrgScope } from "@/lib/tenant";
694	import * as memberRepo from "@/server/repositories/member-repository";
695	import * as orgRepo from "@/server/repositories/organization-repository";
696	import * as sessionRepo from "@/server/repositories/session-repository";
697	import { toIsoTimestamp } from "@/types/common";
698	import type { SwitchOrgInput } from "@/schemas/session";
699	import type { IsoTimestamp, UserId } from "@/types/common";
700	import type { Actor, SessionPrincipal } from "@/types/member";
701	
702	/** How long a freshly issued session cookie stays valid. */
703	const SESSION_TTL_DAYS = 30;
704	const MS_PER_DAY = 24 * 60 * 60 * 1000;
705	
706	/** Length in bytes of the raw session token handed to the browser. */
707	const TOKEN_BYTES = 32;
708	
709	/**
710	 * Mints a session. Only the hash reaches the database, so a dump of the
711	 * `sessions` table cannot be replayed as a login.
712	 */
713	export async function createSessionToken(
714	  userId: UserId,
715	): Promise<{ token: string; expiresAt: IsoTimestamp }> {
716	  const token = randomToken(TOKEN_BYTES);
717	  const expiresAt = toIsoTimestamp(
718	    new Date(Date.now() + SESSION_TTL_DAYS * MS_PER_DAY),
719	  );
720	
721	  await sessionRepo.createSession(userId, hashToken(token), expiresAt);
722	
723	  return { token, expiresAt };
724	}
725	
726	export async function resolveSession(
727	  token: string,
728	): Promise<SessionPrincipal | null> {
729	  return sessionRepo.findSessionByTokenHash(hashToken(token));
730	}
