732	/**
733	 * The bridge between "who is logged in" and "what may they do here": given a
734	 * principal and the org slug in the URL, produce the `Actor` every service
735	 * method takes, or `null` when the user is not a member of that org.
736	 *
737	 * The `assertOrgScope` call at the end looks redundant — the actor was just
738	 * built from that org — but it is the invariant this whole layer exists to
739	 * uphold, and it catches a mis-wired membership lookup immediately.
740	 */
741	export async function resolveActorForOrg(
742	  principal: SessionPrincipal,
743	  orgSlug: string,
744	): Promise<Actor | null> {
745	  const org = await orgRepo.findOrgBySlug(orgSlug);
746	  if (!org) return null;
747	
748	  const member = await memberRepo.findMember(org.id, principal.userId);
749	  if (!member || member.status !== "active") return null;
750	
751	  const actor: Actor = {
752	    userId: principal.userId,
753	    orgId: org.id,
754	    role: member.role,
755	  };
756	
757	  assertOrgScope(actor, org.id);
758	
759	  await memberRepo.touchLastSeen(
760	    org.id,
761	    principal.userId,
762	    toIsoTimestamp(new Date()),
763	  );
764	
765	  return actor;
766	}
