768	/**
769	 * Switches the org a session defaults to. Membership is re-checked here so a
770	 * removed member cannot pin their cookie to an org they left.
771	 *
772	 * `SessionPrincipal` carries no session id, so the write to `sessions.
773	 * active_org_id` (`sessionRepository.setActiveOrg`) happens in the Server
774	 * Action, which still holds the cookie. This method owns the authorization
775	 * half of the switch.
776	 */
777	export async function switchActiveOrg(
778	  principal: SessionPrincipal,
779	  input: SwitchOrgInput,
780	): Promise<void> {
781	  const member = await memberRepo.findMember(input.orgId, principal.userId);
782	  if (!member || member.status !== "active") {
783	    throw new Error("You are not a member of that organization");
784	  }
785	
786	  const orgs = await orgRepo.listOrgsForUser(principal.userId);
787	  const target = orgs.find((org) => org.id === input.orgId);
788	  if (!target) throw new Error("You are not a member of that organization");
789	
790	  assertOrgScope(
791	    { userId: principal.userId, orgId: input.orgId, role: member.role },
792	    target.id,
793	  );
794	}
