883	/** Groups a feed page by calendar day, newest day first. */
884	export function groupByDay(
885	  events: readonly ActivityEvent[],
886	): readonly ActivityGroup[] {
887	  const byDay = new Map<string, ActivityEvent[]>();
888	
889	  for (const event of events) {
890	    const day = event.occurredAt.slice(0, 10);
891	    const bucket = byDay.get(day) ?? [];
892	    bucket.push(event);
893	    byDay.set(day, bucket);
894	  }
