475	export function findMentionQuery(
476	  body: string,
477	  caret: number,
478	): MentionQuery | null {
479	  const upTo = body.slice(0, Math.max(0, Math.min(caret, body.length)));
480	  const at = upTo.lastIndexOf("@");
