cat > tests/services/zz-tmp-suspend.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as memberService from "@/server/services/member-service";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import { notify } from "@/server/services/notification-service";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("works", async () => {
  const t = await createTenant("susp", "growth");
  const m = (await memberRepo.findMember(t.org.id, t.userIds.member))!;
  const o = (await memberRepo.findMember(t.org.id, t.userIds.owner))!;
  await expect(memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: o.id })).rejects.toThrow();
  await expect(memberService.suspendMember(t.actors.owner, { orgId: t.org.id, memberId: o.id })).rejects.toThrow();
  const s = await memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: m.id });
  expect(s.status).toBe("suspended");
  expect(await memberRepo.countActiveMembers(t.org.id)).toBe(4);
  expect((await usageRepo.recomputeUsage(t.org.id)).seatsUsed).toBe(4);
  expect(await memberService.resolveActor(t.userIds.member, t.org.id)).toBeNull();
  expect(await orgRepo.listOrgsForUser(t.userIds.member)).toHaveLength(0);
  expect(await notify(t.org.id, "issue_assigned", [t.userIds.member], { title: "a", body: "b", href: "/", actorId: null })).toHaveLength(0);
  await expect(issueService.createIssue(t.actors.admin, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }))).rejects.toBeInstanceOf(memberService.MemberSuspendedError);
  const issue = await issueService.createIssue(t.actors.admin, issueInput(t.org.id, t.project.id));
  await expect(issueService.assignIssue(t.actors.admin, { orgId: t.org.id, issueId: issue.id, assigneeId: t.userIds.member })).rejects.toBeInstanceOf(memberService.MemberSuspendedError);
  const c = await commentService.createComment(t.actors.admin, { orgId: t.org.id, issueId: issue.id, body: "hi @member @viewer", parentId: null, mentionedUserIds: [t.userIds.member] } as never);
  expect(c.mentionedUserIds).toEqual([t.userIds.viewer]);
  let acts = await listActivity(t.actors.owner, { orgId: t.org.id, action: ["member.suspended"], limit: 10, cursor: null });
  expect(acts.items).toHaveLength(1);
  const off = registerActivityListeners();
  const r = await memberService.reinstateMember(t.actors.admin, { orgId: t.org.id, memberId: m.id });
  off();
  expect(r.status).toBe("active");
  acts = await listActivity(t.actors.owner, { orgId: t.org.id, action: ["member.reinstated"], limit: 10, cursor: null });
  expect(acts.items).toHaveLength(1);
  expect(await memberService.resolveActor(t.userIds.member, t.org.id)).not.toBeNull();
  await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: m.id });
  expect(await memberRepo.countActiveMembers(t.org.id)).toBe(3);
  await expect(memberService.suspendMember(t.actors.owner, { orgId: t.org.id, memberId: m.id })).rejects.toBeInstanceOf(NotFoundError);
});
EOF
